custom_css:
/* TALL BUTTONS */
.customButton { padding: 60px; }

.fusion-title-heading {
 text-transform: none !important;   
}
.ynki-post-slider h2 {
    font-size: clamp(1.17rem, 0.934rem + 0.629vw, 1.5rem) !important;
}
.tablecontainer {
  overflow-x: auto;
  margin-bottom: 1.5rem;
}
.awb-imageframe-caption-text, .wp-element-caption {
--awb-caption-text-size: 0.813rem;
}
.wp-element-caption {
font-size: 0.813rem;
}
table, th, td {
  border: 1px solid !important;
}
th, td {
  padding: 5px;
    font-size:1rem;
}
.tablecaption, th {
    font-weight: bold !important;
}
tr:nth-child(even) {
    background-color:#f2f2f2;
}
tfoot td {
    font-style: italic;
}
.footer-ynki {
    font-size:clamp(0.875rem, 0.688rem + 0.5vw, 1rem);
}
.angka-tabel {
    text-align: right;
}
td {
    vertical-align: top;
}
thead {
    font-weight: bold;
    text-align: center;
    vertical-align: middle;
}
thead td {
    vertical-align: middle;
}
thead th {
  position: sticky;
  top: 0;
  background-color: #FFFFFF;
}
@media screen and (max-width: 600px) {
  table thead {
    border: none;
    clip: rect(0 0 0 0);
    height: 1px;
    margin: -1px;
    overflow: hidden;
    padding: 0;
    position: absolute;
    width: 1px;
  }
  
  table tr {
    border: 3px solid #ddd;
    display: block;
    margin-bottom: 1rem;
  }
  
  table td {
    border-bottom: 1px solid #ddd;
    display: block;
    text-align: right;
  }
  
  table td::before {
    content: attr(data-label);
    float: left;
	font-weight: bold;
  }
  table {
  border: none !important;
}
}
.ynki-post-slider {
    /*border-bottom: 1px !important;
    border-style: solid;*/
}
.fusion-flexslider.flexslider-posts .slide-excerpt {
    bottom: 0;
}
.visi-misi-ynki li, .visi-misi-ynki p {
    color: #ffffff;
}
.con-visi-misi-ynki {
display:flex;
align-items: stretch;
}
.ynki-tabs-profil li.active  {
	--awb-title-active-text-color:#65bc7b;
	font-weight: bold;
}
.ynki-tabs-profil img  {
	margin-right: 1rem;
}
.ynki-tabs-profil a.tab-link:hover  {
	color: black;
}
